import React, { useState, useEffect } from "react";
import {
    Box, Typography, Button, CircularProgress, TextField, Dialog, DialogTitle,
    DialogContent, DialogActions, Card, CardContent, CardActions, Chip
} from "@mui/material";
import { AlertColor } from "@mui/material/Alert";
import WarningIcon from '@mui/icons-material/Warning';
import LockOpenIcon from '@mui/icons-material/LockOpen';
import PersonIcon from '@mui/icons-material/Person';
import EditIcon from '@mui/icons-material/Edit';
import CloudIcon from '@mui/icons-material/Cloud';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import RadioButtonUncheckedIcon from '@mui/icons-material/RadioButtonUnchecked';
import RadioButtonCheckedIcon from '@mui/icons-material/RadioButtonChecked';
import KeyIcon from '@mui/icons-material/Key';
import DeleteIcon from '@mui/icons-material/Delete';
import StarIcon from '@mui/icons-material/Star';
import { useAuth } from "auth/AuthContext";
import { useUser, useClerk, useAuth as useClerkAuth } from "@clerk/clerk-react";

type AuthMode = 'none' | 'local' | 'cloud';

interface UserManagementProps {
    showSnackbar: (message: string, severity?: AlertColor) => void;
}

interface LicenseInfo {
    hasValidLicense: boolean;
    licenseMessage?: string;
}

const Settings_UserManagement: React.FC<UserManagementProps> = ({ showSnackbar }) => {
    // Local auth context
    const { logout, user, login } = useAuth();

    // Clerk cloud auth context
    const { user: clerkUser, isLoaded: clerkLoaded, isSignedIn } = useUser();
    const { signOut, openSignIn } = useClerk();
    const { getToken } = useClerkAuth();

    // Authentication state
    const [authMode, setAuthMode] = useState<AuthMode>('none');
    const [authLoading, setAuthLoading] = useState<boolean>(false);
    const [licenseInfo, setLicenseInfo] = useState<LicenseInfo>({ hasValidLicense: false });
    const [licenseLoading, setLicenseLoading] = useState<boolean>(false);

    // Dialog states for user management
    const [usernameDialogOpen, setUsernameDialogOpen] = useState<boolean>(false);
    const [newUsername, setNewUsername] = useState<string>('');
    const [usernameLoading, setUsernameLoading] = useState<boolean>(false);
    const [passwordDialogOpen, setPasswordDialogOpen] = useState<boolean>(false);
    const [currentPassword, setCurrentPassword] = useState<string>('');
    const [newPassword, setNewPassword] = useState<string>('');
    const [confirmPassword, setConfirmPassword] = useState<string>('');
    const [passwordLoading, setPasswordLoading] = useState<boolean>(false);
    const [removeUserDialogOpen, setRemoveUserDialogOpen] = useState<boolean>(false);
    const [removeUserLoading, setRemoveUserLoading] = useState<boolean>(false);

    // Create Local Admin Dialog
    const [createAdminDialogOpen, setCreateAdminDialogOpen] = useState<boolean>(false);
    const [adminUsername, setAdminUsername] = useState<string>('');
    const [adminPassword, setAdminPassword] = useState<string>('');
    const [adminConfirmPassword, setAdminConfirmPassword] = useState<string>('');
    const [createAdminLoading, setCreateAdminLoading] = useState<boolean>(false);

    useEffect(() => {
        fetchAuthMode();
    }, []);

    // Check license info via JunctionRelay Local Backend (which proxies to JunctionRelay Cloud)
    // ONLY for cloud mode with Clerk authentication - local auth never has license info
    const checkLicenseViaBackend = React.useCallback(async () => {
        if (authMode !== 'cloud' || !clerkLoaded || !isSignedIn || !clerkUser) {
            setLicenseInfo({ hasValidLicense: false });
            return;
        }

        try {
            setLicenseLoading(true);
            const token = await getToken({ template: "junctionrelay-cloud" });

            const response = await fetch("/api/auth/check-license", {
                headers: {
                    "Authorization": `Bearer ${token}`,
                    "Content-Type": "application/json"
                }
            });

            if (response.ok) {
                const data = await response.json();
                setLicenseInfo({
                    hasValidLicense: data.hasValidLicense || false,
                    licenseMessage: data.message || ""
                });
            } else {
                setLicenseInfo({
                    hasValidLicense: false,
                    licenseMessage: "Failed to check license"
                });
            }
        } catch (err) {
            console.error("Error checking license via backend:", err);
            setLicenseInfo({
                hasValidLicense: false,
                licenseMessage: "License check failed"
            });
        } finally {
            setLicenseLoading(false);
        }
    }, [authMode, clerkLoaded, isSignedIn, clerkUser, getToken]);

    useEffect(() => {
        if (authMode === 'cloud') {
            checkLicenseViaBackend();
        } else {
            setLicenseInfo({ hasValidLicense: false });
        }
    }, [authMode, checkLicenseViaBackend]);

    const fetchAuthMode = async () => {
        try {
            const authRes = await fetch("/api/auth/mode");
            if (authRes.ok) {
                const authData = await authRes.json();
                setAuthMode(authData.mode || 'none');
            }
        } catch (err) {
            console.error("Error loading auth mode:", err);
        }
    };

    const handleAuthModeChange = async (newMode: AuthMode) => {
        // Handle different modes with proper authentication order
        if (newMode === 'none') {
            // For 'none' mode, just set the mode (no auth needed)
            await setAuthModeInDb(newMode);
        } else if (newMode === 'local') {
            // For local mode, create admin first, then set mode
            handleLocalModeSetup();
        } else if (newMode === 'cloud') {
            // For cloud mode, authenticate first, then set mode
            handleCloudModeSetup();
        }
    };

    const setAuthModeInDb = async (newMode: AuthMode) => {
        try {
            setAuthLoading(true);

            const response = await fetch("/api/auth/set-mode", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ mode: newMode })
            });

            if (response.ok) {
                setAuthMode(newMode);

                // Clear tokens when switching modes
                if (newMode !== 'local') {
                    logout();
                }
                if (newMode !== 'cloud' && isSignedIn) {
                    await signOut();
                }

                const modeNames = { none: 'No Authentication', local: 'Local Authentication', cloud: 'JunctionRelay Cloud' };
                showSnackbar(`Authentication mode changed to: ${modeNames[newMode]}`, "success");

                // Trigger page reload to let backend handle auth requirements
                setTimeout(() => {
                    window.location.reload();
                }, 1000);
            } else {
                const error = await response.json();
                throw new Error(error.message || "Failed to change authentication mode");
            }
        } catch (error: any) {
            showSnackbar(error.message || "Error changing authentication mode", "error");
        } finally {
            setAuthLoading(false);
        }
    };

    const handleLocalModeSetup = () => {
        // Check if local user already exists
        if (user) {
            // User already exists, just set the mode
            setAuthModeInDb('local');
        } else {
            // No user exists, show create admin dialog
            setCreateAdminDialogOpen(true);
        }
    };

    const handleCloudModeSetup = async () => {
        // Check if already signed in to Clerk
        if (clerkLoaded && isSignedIn && clerkUser) {
            // Already authenticated, just set the mode
            await setAuthModeInDb('cloud');
        } else {
            // Not authenticated, show login dialog and wait for success
            try {
                setAuthLoading(true);
                openSignIn();

                // We'll need to detect when Clerk login completes
                // This is handled by the Clerk hooks, but we can show a message
                showSnackbar("Please complete cloud authentication to enable this mode", "info");

                // Note: The actual mode setting will happen when Clerk detects successful login
                // We'll need to add a useEffect to watch for this
            } catch (error) {
                console.error("Error opening Clerk sign in:", error);
                showSnackbar("Error opening login dialog", "error");
            } finally {
                setAuthLoading(false);
            }
        }
    };

    // Watch for successful Clerk login to complete cloud mode setup
    useEffect(() => {
        if (authMode === 'none' && clerkLoaded && isSignedIn && clerkUser && authLoading) {
            // User just completed cloud login, now set the mode
            setAuthModeInDb('cloud');
        }
    }, [clerkLoaded, isSignedIn, clerkUser, authMode, authLoading]);

    const handleCreateLocalAdmin = async () => {
        if (!adminUsername.trim()) {
            showSnackbar("Username cannot be empty", "error");
            return;
        }
        if (adminUsername.trim().length < 3) {
            showSnackbar("Username must be at least 3 characters long", "error");
            return;
        }
        if (!adminPassword || !adminConfirmPassword) {
            showSnackbar("All password fields are required", "error");
            return;
        }
        if (adminPassword !== adminConfirmPassword) {
            showSnackbar("Passwords do not match", "error");
            return;
        }
        if (adminPassword.length < 6) {
            showSnackbar("Password must be at least 6 characters long", "error");
            return;
        }

        try {
            setCreateAdminLoading(true);

            // 1. Create the local user
            const createResponse = await fetch("/api/auth/create-user", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    username: adminUsername.trim(),
                    password: adminPassword
                })
            });

            if (!createResponse.ok) {
                const error = await createResponse.json();
                throw new Error(error.message || "Failed to create admin user");
            }

            // 2. Login with the new credentials
            const loginSuccess = await login(adminUsername.trim(), adminPassword);
            if (!loginSuccess) {
                throw new Error("Failed to login with new admin credentials");
            }

            // 3. Set the auth mode to local
            await setAuthModeInDb('local');

            // 4. Close dialog and reset form
            setCreateAdminDialogOpen(false);
            setAdminUsername("");
            setAdminPassword("");
            setAdminConfirmPassword("");

            showSnackbar("Local admin created successfully and logged in", "success");

        } catch (error: any) {
            showSnackbar(error.message || "Error creating local admin", "error");
        } finally {
            setCreateAdminLoading(false);
        }
    };

    const handleCloudLogin = () => {
        try {
            openSignIn();
        } catch (error) {
            console.error("Error opening Clerk sign in:", error);
            showSnackbar("Error opening login dialog", "error");
        }
    };

    const handleUsernameChange = async () => {
        if (!newUsername.trim()) {
            showSnackbar("Username cannot be empty", "error");
            return;
        }
        if (newUsername.trim().length < 3) {
            showSnackbar("Username must be at least 3 characters long", "error");
            return;
        }

        try {
            setUsernameLoading(true);
            const response = await fetch("/api/auth/change-username", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ newUsername: newUsername.trim() })
            });

            if (response.ok) {
                setUsernameDialogOpen(false);
                setNewUsername("");
                logout();
                showSnackbar("Username updated successfully. Please log in with your new username.", "success");
                setTimeout(() => window.location.reload(), 1000);
            } else {
                const error = await response.json();
                throw new Error(error.message || "Failed to update username");
            }
        } catch (error: any) {
            showSnackbar(error.message || "Error updating username", "error");
        } finally {
            setUsernameLoading(false);
        }
    };

    const handlePasswordChange = async () => {
        if (!currentPassword || !newPassword || !confirmPassword) {
            showSnackbar("All password fields are required", "error");
            return;
        }
        if (newPassword !== confirmPassword) {
            showSnackbar("New passwords do not match", "error");
            return;
        }
        if (newPassword.length < 6) {
            showSnackbar("New password must be at least 6 characters long", "error");
            return;
        }

        try {
            setPasswordLoading(true);
            const response = await fetch("/api/auth/change-password", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    currentPassword: currentPassword,
                    newPassword: newPassword
                })
            });

            if (response.ok) {
                setPasswordDialogOpen(false);
                setCurrentPassword("");
                setNewPassword("");
                setConfirmPassword("");
                showSnackbar("Password changed successfully.", "success");
            } else {
                const error = await response.json();
                throw new Error(error.message || "Failed to change password");
            }
        } catch (error: any) {
            showSnackbar(error.message || "Error changing password", "error");
        } finally {
            setPasswordLoading(false);
        }
    };

    const handleRemoveLocalUser = async () => {
        try {
            setRemoveUserLoading(true);
            const response = await fetch("/api/auth/remove-user", {
                method: "DELETE",
                headers: { "Content-Type": "application/json" }
            });

            if (response.ok) {
                setRemoveUserDialogOpen(false);
                logout();
                showSnackbar("Local user removed successfully. You can now create a new admin account.", "success");
                setTimeout(() => window.location.reload(), 1000);
            } else {
                const error = await response.json();
                throw new Error(error.message || "Failed to remove user");
            }
        } catch (error: any) {
            showSnackbar(error.message || "Error removing user", "error");
        } finally {
            setRemoveUserLoading(false);
        }
    };

    return (
        <>
            {/* Authentication Mode Cards */}
            <Box sx={{ mb: 4 }}>
                <Typography variant="h6" gutterBottom sx={{ mb: 2 }}>
                    Authentication Mode
                </Typography>

                <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: 2 }}>
                    {/* No Authentication Card */}
                    <Card
                        sx={{
                            border: authMode === 'none' ? '2px solid' : '1px solid',
                            borderColor: authMode === 'none' ? 'primary.main' : 'divider',
                            cursor: 'pointer',
                            transition: 'all 0.2s',
                            minHeight: '320px',
                            '&:hover': { borderColor: 'primary.main' }
                        }}
                        onClick={() => !authLoading && handleAuthModeChange('none')}
                    >
                        <CardContent sx={{ height: '260px', display: 'flex', flexDirection: 'column' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                <LockOpenIcon sx={{ mr: 1, color: authMode === 'none' ? 'primary.main' : 'text.secondary' }} />
                                <Typography variant="h6">No Authentication</Typography>
                                <Box sx={{ ml: 'auto' }}>
                                    {authMode === 'none' ?
                                        <RadioButtonCheckedIcon color="primary" /> :
                                        <RadioButtonUncheckedIcon color="disabled" />
                                    }
                                </Box>
                            </Box>

                            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                Open access with no login required. Anyone with network access can view and modify settings.
                            </Typography>

                            {authMode === 'none' && (
                                <Typography variant="caption" color="warning.main" sx={{
                                    mt: 'auto',
                                    fontWeight: 'medium',
                                    display: 'flex',
                                    alignItems: 'center'
                                }}>
                                    <WarningIcon sx={{ mr: 0.5, fontSize: 14 }} />
                                    Use only in trusted environments
                                </Typography>
                            )}
                        </CardContent>

                        <CardActions>
                            <Button
                                size="small"
                                variant={authMode === 'none' ? 'contained' : 'outlined'}
                                disabled={authLoading || authMode === 'none'}
                                fullWidth
                            >
                                {authMode === 'none' ? 'Active' : 'Select'}
                            </Button>
                        </CardActions>
                    </Card>

                    {/* Local Authentication Card */}
                    <Card
                        sx={{
                            border: authMode === 'local' ? '2px solid' : '1px solid',
                            borderColor: authMode === 'local' ? 'primary.main' : 'divider',
                            cursor: authMode === 'local' ? 'default' : 'pointer',
                            transition: 'all 0.2s',
                            minHeight: '320px',
                            '&:hover': { borderColor: 'primary.main' }
                        }}
                        onClick={() => !authLoading && authMode !== 'local' && handleAuthModeChange('local')}
                    >
                        <CardContent sx={{ height: '260px', display: 'flex', flexDirection: 'column' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                <PersonIcon sx={{ mr: 1, color: authMode === 'local' ? 'primary.main' : 'text.secondary' }} />
                                <Typography variant="h6">Local Authentication</Typography>
                                <Box sx={{ ml: 'auto' }}>
                                    {authMode === 'local' ?
                                        <RadioButtonCheckedIcon color="primary" /> :
                                        <RadioButtonUncheckedIcon color="disabled" />
                                    }
                                </Box>
                            </Box>

                            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                Local admin account with offline authentication. Secure access with username and password.
                            </Typography>

                            {/* User management - when logged in to local auth */}
                            {authMode === 'local' && user && (
                                <Box sx={{ mt: 'auto' }}>
                                    <Typography variant="subtitle2" sx={{ mb: 1, display: 'flex', alignItems: 'center' }}>
                                        <CheckCircleIcon sx={{ mr: 1, fontSize: 18, color: 'success.main' }} />
                                        Logged in as: {user.username}
                                    </Typography>
                                    <Box sx={{ display: 'flex', gap: 1 }}>
                                        <Button
                                            size="small"
                                            variant="outlined"
                                            startIcon={<EditIcon />}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                setNewUsername(user.username);
                                                setUsernameDialogOpen(true);
                                            }}
                                            sx={{ fontSize: '0.75rem', flexGrow: 1 }}
                                        >
                                            Change Username
                                        </Button>
                                        <Button
                                            size="small"
                                            variant="outlined"
                                            startIcon={<KeyIcon />}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                setPasswordDialogOpen(true);
                                            }}
                                            sx={{ fontSize: '0.75rem', flexGrow: 1 }}
                                        >
                                            Change Password
                                        </Button>
                                    </Box>
                                </Box>
                            )}

                            {/* Remove Local User - when NOT in local mode but user exists */}
                            {authMode !== 'local' && user && (
                                <Box sx={{ mt: 'auto' }}>
                                    <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 1 }}>
                                        Local user account exists but not currently active
                                    </Typography>
                                    <Button
                                        size="small"
                                        variant="outlined"
                                        color="error"
                                        startIcon={<DeleteIcon />}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            setRemoveUserDialogOpen(true);
                                        }}
                                        sx={{ fontSize: '0.75rem' }}
                                        fullWidth
                                    >
                                        Remove Local User
                                    </Button>
                                </Box>
                            )}
                        </CardContent>

                        <CardActions>
                            <Button
                                size="small"
                                variant={authMode === 'local' ? 'contained' : 'outlined'}
                                disabled={authLoading || authMode === 'local'}
                                fullWidth
                            >
                                {authMode === 'local' ? 'Active' : 'Select'}
                            </Button>
                        </CardActions>
                    </Card>

                    {/* JunctionRelay Cloud Card */}
                    <Card
                        sx={{
                            border: authMode === 'cloud' ? '2px solid' : '1px solid',
                            borderColor: authMode === 'cloud' ? 'primary.main' : 'divider',
                            cursor: authMode === 'cloud' ? 'default' : 'pointer',
                            transition: 'all 0.2s',
                            minHeight: '320px',
                            '&:hover': { borderColor: 'primary.main' }
                        }}
                        onClick={() => !authLoading && authMode !== 'cloud' && handleAuthModeChange('cloud')}
                    >
                        <CardContent sx={{ height: '260px', display: 'flex', flexDirection: 'column' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                <CloudIcon sx={{ mr: 1, color: authMode === 'cloud' ? 'primary.main' : 'text.secondary' }} />
                                <Typography variant="h6">JunctionRelay Cloud</Typography>
                                <Box sx={{ ml: 'auto' }}>
                                    {authMode === 'cloud' ?
                                        <RadioButtonCheckedIcon color="primary" /> :
                                        <RadioButtonUncheckedIcon color="disabled" />
                                    }
                                </Box>
                            </Box>

                            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                Support the project by enabling online authentication and considering a JunctionRelay Pro License. While the current Early Access Pro license does not yet provide additional features, it helps fund continued development. Upcoming features include remote management, OTA firmware updates, automatic updates, notifications, and cloud backups.
                            </Typography>

                            {/* Cloud user management - when logged in */}
                            {authMode === 'cloud' && clerkLoaded && isSignedIn && clerkUser && (
                                <Box sx={{ mt: 'auto' }}>
                                    <Typography variant="subtitle2" sx={{ mb: 1, display: 'flex', alignItems: 'center' }}>
                                        <CheckCircleIcon sx={{ mr: 1, fontSize: 18, color: 'success.main' }} />
                                        {clerkUser.primaryEmailAddress?.emailAddress || 'Cloud User'}
                                    </Typography>

                                    {/* License Status */}
                                    <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                                        {licenseLoading ? (
                                            <>
                                                <CircularProgress size={14} sx={{ mr: 0.5 }} />
                                                <Typography variant="caption">
                                                    Checking license...
                                                </Typography>
                                            </>
                                        ) : (
                                            <>
                                                {licenseInfo.hasValidLicense ? (
                                                    <Chip
                                                        icon={<StarIcon />}
                                                        label="Pro License"
                                                        color="primary"
                                                        size="small"
                                                        sx={{ fontSize: '0.75rem' }}
                                                    />
                                                ) : (
                                                    <Chip
                                                        label="Free Account"
                                                        color="default"
                                                        size="small"
                                                        sx={{ fontSize: '0.75rem' }}
                                                    />
                                                )}
                                            </>
                                        )}
                                    </Box>

                                    {licenseInfo.licenseMessage && (
                                        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 1 }}>
                                            {licenseInfo.licenseMessage}
                                        </Typography>
                                    )}
                                </Box>
                            )}

                            {/* Cloud login - when not logged in */}
                            {authMode === 'cloud' && clerkLoaded && (!isSignedIn || !clerkUser) && (
                                <Box sx={{ mt: 'auto' }}>
                                    <Typography variant="caption" sx={{ display: 'block', mb: 1 }}>
                                        Please log in to access cloud features
                                    </Typography>
                                    <Button
                                        size="small"
                                        variant="contained"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            handleCloudLogin();
                                        }}
                                        sx={{ fontSize: '0.75rem' }}
                                        fullWidth
                                    >
                                        Login with JunctionRelay Cloud
                                    </Button>
                                </Box>
                            )}

                            {/* Loading state for Clerk */}
                            {authMode === 'cloud' && !clerkLoaded && (
                                <Box sx={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    mt: 'auto'
                                }}>
                                    <CircularProgress size={16} sx={{ mr: 1 }} />
                                    <Typography variant="caption">
                                        Loading authentication...
                                    </Typography>
                                </Box>
                            )}
                        </CardContent>

                        <CardActions>
                            <Button
                                size="small"
                                variant={authMode === 'cloud' ? 'contained' : 'outlined'}
                                disabled={authLoading || authMode === 'cloud'}
                                fullWidth
                            >
                                {authMode === 'cloud' ? 'Active' : 'Select'}
                            </Button>
                        </CardActions>
                    </Card>
                </Box>

                {authLoading && (
                    <Box sx={{ display: 'flex', justifyContent: 'center', mt: 2 }}>
                        <CircularProgress size={24} />
                    </Box>
                )}
            </Box>

            {/* Create Local Admin Dialog */}
            <Dialog
                open={createAdminDialogOpen}
                onClose={() => {
                    setCreateAdminDialogOpen(false);
                    setAdminUsername('');
                    setAdminPassword('');
                    setAdminConfirmPassword('');
                }}
                maxWidth="sm"
                fullWidth
            >
                <DialogTitle>Create Local Admin Account</DialogTitle>
                <DialogContent>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Create an administrator account to secure access to your JunctionRelay device.
                    </Typography>
                    <TextField
                        autoFocus
                        margin="dense"
                        label="Admin Username"
                        type="text"
                        fullWidth
                        variant="outlined"
                        value={adminUsername}
                        onChange={(e) => setAdminUsername(e.target.value)}
                        disabled={createAdminLoading}
                        helperText="Username must be at least 3 characters long"
                        sx={{ mb: 2 }}
                    />
                    <TextField
                        margin="dense"
                        label="Admin Password"
                        type="password"
                        fullWidth
                        variant="outlined"
                        value={adminPassword}
                        onChange={(e) => setAdminPassword(e.target.value)}
                        disabled={createAdminLoading}
                        helperText="Password must be at least 6 characters long"
                        sx={{ mb: 2 }}
                    />
                    <TextField
                        margin="dense"
                        label="Confirm Password"
                        type="password"
                        fullWidth
                        variant="outlined"
                        value={adminConfirmPassword}
                        onChange={(e) => setAdminConfirmPassword(e.target.value)}
                        disabled={createAdminLoading}
                        error={adminConfirmPassword.length > 0 && adminPassword !== adminConfirmPassword}
                        helperText={adminConfirmPassword.length > 0 && adminPassword !== adminConfirmPassword ? "Passwords do not match" : ""}
                    />
                </DialogContent>
                <DialogActions>
                    <Button
                        onClick={() => {
                            setCreateAdminDialogOpen(false);
                            setAdminUsername('');
                            setAdminPassword('');
                            setAdminConfirmPassword('');
                        }}
                        disabled={createAdminLoading}
                    >
                        Cancel
                    </Button>
                    <Button
                        onClick={handleCreateLocalAdmin}
                        variant="contained"
                        disabled={createAdminLoading || !adminUsername.trim() || adminUsername.trim().length < 3 || !adminPassword || !adminConfirmPassword || adminPassword !== adminConfirmPassword}
                        startIcon={createAdminLoading ? <CircularProgress size={16} /> : undefined}
                    >
                        {createAdminLoading ? 'Creating...' : 'Create Admin Account'}
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Username Change Dialog */}
            <Dialog
                open={usernameDialogOpen}
                onClose={() => {
                    setUsernameDialogOpen(false);
                    setNewUsername('');
                }}
                maxWidth="sm"
                fullWidth
            >
                <DialogTitle>Change Username</DialogTitle>
                <DialogContent>
                    <TextField
                        autoFocus
                        margin="dense"
                        label="New Username"
                        type="text"
                        fullWidth
                        variant="outlined"
                        value={newUsername}
                        onChange={(e) => setNewUsername(e.target.value)}
                        disabled={usernameLoading}
                        helperText="Username must be at least 3 characters long"
                    />
                </DialogContent>
                <DialogActions>
                    <Button
                        onClick={() => {
                            setUsernameDialogOpen(false);
                            setNewUsername('');
                        }}
                        disabled={usernameLoading}
                    >
                        Cancel
                    </Button>
                    <Button
                        onClick={handleUsernameChange}
                        variant="contained"
                        disabled={usernameLoading || newUsername.trim().length < 3}
                        startIcon={usernameLoading ? <CircularProgress size={16} /> : undefined}
                    >
                        {usernameLoading ? 'Updating...' : 'Update Username'}
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Password Change Dialog */}
            <Dialog
                open={passwordDialogOpen}
                onClose={() => {
                    setPasswordDialogOpen(false);
                    setCurrentPassword('');
                    setNewPassword('');
                    setConfirmPassword('');
                }}
                maxWidth="sm"
                fullWidth
            >
                <DialogTitle>Change Password</DialogTitle>
                <DialogContent>
                    <TextField
                        autoFocus
                        margin="dense"
                        label="Current Password"
                        type="password"
                        fullWidth
                        variant="outlined"
                        value={currentPassword}
                        onChange={(e) => setCurrentPassword(e.target.value)}
                        disabled={passwordLoading}
                        sx={{ mb: 2 }}
                    />
                    <TextField
                        margin="dense"
                        label="New Password"
                        type="password"
                        fullWidth
                        variant="outlined"
                        value={newPassword}
                        onChange={(e) => setNewPassword(e.target.value)}
                        disabled={passwordLoading}
                        helperText="Password must be at least 6 characters long"
                        sx={{ mb: 2 }}
                    />
                    <TextField
                        margin="dense"
                        label="Confirm New Password"
                        type="password"
                        fullWidth
                        variant="outlined"
                        value={confirmPassword}
                        onChange={(e) => setConfirmPassword(e.target.value)}
                        disabled={passwordLoading}
                        error={confirmPassword.length > 0 && newPassword !== confirmPassword}
                        helperText={confirmPassword.length > 0 && newPassword !== confirmPassword ? "Passwords do not match" : ""}
                    />
                </DialogContent>
                <DialogActions>
                    <Button
                        onClick={() => {
                            setPasswordDialogOpen(false);
                            setCurrentPassword('');
                            setNewPassword('');
                            setConfirmPassword('');
                        }}
                        disabled={passwordLoading}
                    >
                        Cancel
                    </Button>
                    <Button
                        onClick={handlePasswordChange}
                        variant="contained"
                        disabled={passwordLoading || !currentPassword || !newPassword || !confirmPassword || newPassword !== confirmPassword}
                        startIcon={passwordLoading ? <CircularProgress size={16} /> : undefined}
                    >
                        {passwordLoading ? 'Changing...' : 'Change Password'}
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Remove Local User Dialog */}
            <Dialog
                open={removeUserDialogOpen}
                onClose={() => {
                    setRemoveUserDialogOpen(false);
                }}
                maxWidth="sm"
                fullWidth
            >
                <DialogTitle sx={{ display: 'flex', alignItems: 'center' }}>
                    <WarningIcon sx={{ mr: 1, color: 'warning.main' }} />
                    Remove Local User
                </DialogTitle>
                <DialogContent>
                    <Typography variant="body1" sx={{ mb: 2 }}>
                        Are you sure you want to remove the local user account? This action cannot be undone.
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                        After removing the user, you will be logged out and can create a new admin account.
                    </Typography>
                </DialogContent>
                <DialogActions>
                    <Button
                        onClick={() => {
                            setRemoveUserDialogOpen(false);
                        }}
                        disabled={removeUserLoading}
                    >
                        Cancel
                    </Button>
                    <Button
                        onClick={handleRemoveLocalUser}
                        variant="contained"
                        color="error"
                        disabled={removeUserLoading}
                        startIcon={removeUserLoading ? <CircularProgress size={16} /> : <DeleteIcon />}
                    >
                        {removeUserLoading ? 'Removing...' : 'Remove User'}
                    </Button>
                </DialogActions>
            </Dialog>
        </>
    );
};

export default Settings_UserManagement;